package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi/config"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		accountId := cfg.Require("accountId")

		cf, err := createCloudflareResources(ctx, accountId)
		if err != nil {
			return err
		}

		sf, err := createSnowflakeResources(ctx)
		if err != nil {
			return err
		}

		// ===========================================
		// Outputs
		// ===========================================
		ctx.Export("d1DatabaseId", cf.D1DatabaseId)
		ctx.Export("d1DatabaseName", cf.D1DatabaseName)
		ctx.Export("r2BucketName", cf.R2BucketName)
		ctx.Export("kvNamespaceId", cf.KvNamespaceId)
		ctx.Export("snowflakeDatabaseName", sf.DatabaseName)
		ctx.Export("snowflakeSchemaName", sf.SchemaName)
		ctx.Export("snowflakeWarehouseName", sf.WarehouseName)
		ctx.Export("snowflakeAdminDatabaseName", sf.AdminDatabaseName)
		ctx.Export("snowflakeCoreDatabaseName", sf.CoreDatabaseName)
		ctx.Export("snowflakeDbtRoleName", sf.DbtRoleName)
		ctx.Export("snowflakeDbtServiceUserName", sf.DbtServiceUserName)
		ctx.Export("snowflakeGitRepositoryName", sf.GitRepositoryName)

		return nil
	})
}

package main

import (
	"github.com/pulumi/pulumi-cloudflare/sdk/v5/go/cloudflare"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

type CloudflareOutputs struct {
	D1DatabaseId   pulumi.IDOutput
	D1DatabaseName pulumi.StringOutput
	R2BucketName   pulumi.StringOutput
	KvNamespaceId  pulumi.IDOutput
}

func createCloudflareResources(ctx *pulumi.Context, accountId string) (*CloudflareOutputs, error) {
	// ===========================================
	// D1 Database
	// ===========================================
	// 既存のD1データベースをインポートして管理
	// pulumi import cloudflare:index/d1Database:D1Database raw <account_id>/<database_id>
	rawDb, err := cloudflare.NewD1Database(ctx, "raw", &cloudflare.D1DatabaseArgs{
		AccountId: pulumi.String(accountId),
		Name:      pulumi.String("raw"),
	}, pulumi.Protect(true))
	if err != nil {
		return nil, err
	}

	// ===========================================
	// R2 Bucket (for data lake)
	// ===========================================
	dataLake, err := cloudflare.NewR2Bucket(ctx, "data-lake", &cloudflare.R2BucketArgs{
		AccountId: pulumi.String(accountId),
		Name:      pulumi.String("data-lake"),
		Location:  pulumi.String("APAC"),
	})
	if err != nil {
		return nil, err
	}

	// ===========================================
	// Workers KV Namespace (for caching)
	// ===========================================
	cacheKv, err := cloudflare.NewWorkersKvNamespace(ctx, "data-cache", &cloudflare.WorkersKvNamespaceArgs{
		AccountId: pulumi.String(accountId),
		Title:     pulumi.String("data-cache"),
	})
	if err != nil {
		return nil, err
	}

	return &CloudflareOutputs{
		D1DatabaseId:   rawDb.ID(),
		D1DatabaseName: rawDb.Name,
		R2BucketName:   dataLake.Name,
		KvNamespaceId:  cacheKv.ID(),
	}, nil
}

